function archiveStaff(id){if(user?.role!=='admin'||id===1)return;let u=getd(id);if(!u)return;if(u.disabled){u.disabled=false;save();staffManager();return}let available=db.users.filter(x=>x.role==='doctor'&&!x.disabled&&x.id!==id),assigned=db.patients.filter(p=>p.doctor===id),future=db.appointments.filter(a=>a.doctor===id&&a.date>=today()&&!['مكتمل','ملغي'].includes(a.status));openModal(`<h2>أرشفة ${esc(u.name)}</h2><p>سيُمنع الدخول ويُزال من قائمة الأطباء الجدد. تبقى الزيارات السابقة محفوظة.</p><p>${assigned.length} ملف مريض و${future.length} موعد قادم يحتاج نقل للطبيب البديل.</p><form id="archiveStaffForm">${assigned.length||future.length?`<label>الطبيب البديل<select name="replacement" required><option value="">اختر الطبيب</option>${options(available)}</select></label>`:''}<p id="archiveError" class="error"></p><button id="archiveConfirm">تأكيد الأرشفة والحفظ</button></form>`);$('#archiveStaffForm').onsubmit=async e=>{e.preventDefault();let replacement=+new FormData(e.target).get('replacement');if((assigned.length||future.length)&&!available.some(x=>x.id===replacement)){$('#archiveError').textContent='أضف طبيباً بديلاً أولاً ثم انقل الملفات إليه';return}assigned.forEach(p=>p.doctor=replacement);future.forEach(a=>a.doctor=replacement);u.disabled=true;if(await confirmedSave($('#archiveConfirm'),$('#archiveError')))staffManager()};ensureBackButton()}
