function applyModuleOrder(){let grid=$('.modulegrid');if(!grid)return;let order=db.settings.moduleOrder||[];let cards=[...grid.children];cards.sort((a,b)=>{let key=e=>e.dataset.customSection||e.getAttribute('onclick')?.match(/openModule\('([^']+)'\)/)?.[1];return (order.indexOf(key(a))<0?999:order.indexOf(key(a)))-(order.indexOf(key(b))<0?999:order.indexOf(key(b)))});cards.forEach(el=>grid.append(el));if(user.role!=='admin')return;let bar=document.createElement('div');bar.className='row';bar.innerHTML='<button class="secondary">ترتيب الأقسام</button><button>حفظ ترتيب الأقسام</button>';grid.before(bar);bar.children[0].onclick=()=>{cards.forEach(card=>{if(card.querySelector('.moduleMove'))return;let controls=document.createElement('span');controls.className='row moduleMove';for(let [text,delta]of [['↑ / يمين',-1],['↓ / يسار',1]]){let b=document.createElement('span');b.role='button';b.tabIndex=0;b.className='badge';b.textContent=text;b.onclick=e=>{e.stopPropagation();if(delta<0&&card.previousElementSibling)grid.insertBefore(card,card.previousElementSibling);if(delta>0&&card.nextElementSibling)card.nextElementSibling.after(card)};b.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();b.click()}};controls.append(b)}card.append(controls)})};bar.children[1].onclick=async()=>{db.settings.moduleOrder=[...grid.children].map(e=>e.dataset.customSection||e.getAttribute('onclick')?.match(/openModule\('([^']+)'\)/)?.[1]).filter(Boolean);if(await confirmedSave(bar.children[1]))toast('تم حفظ ترتيب الأقسام')}}
